import re,os
from collections import Counter
t2=open(os.environ['RLM_SESSION_DIR']+'/../../sessions/'+os.path.basename(os.environ['RLM_SESSION_DIR'])+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)) \((\d+)x(\d+)\):\n',t2):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t2[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def regions(i):
    H=len(i); W=len(i[0])
    # find separator: full row or column of a single color, colored cell 0 not in majority
    for c in range(W):
        col=set(r[c] for r in i)
        if len(col)==1 and list(col)[0]!=Counter(x for r in i for x in r).most_common(1)[0][0]:
            return [r[:c] for r in i],[[r[j] for j in range(c+1,W)] for r in i]
    for r in range(H):
        row=set(i[r])
        if len(row)==1 and list(row)[0]!=Counter(x for row2 in i for x in row2).most_common(1)[0][0]:
            return i[:r],i[r+1:]
    return None,None

def f(i):
    A,B=regions(i)
    ca=Counter(x for r in A for x in r); cb=Counter(x for r in B for x in r)
    common=[c for c in ca if c in cb]
    fill=common[0] if len(common)==1 else None
    return [[3 if A[r][c]==B[r][c] else fill for c in range(len(A[0]))] for r in range(len(A))], common

for k in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
    p,common=f(G[k+' input'])
    print(k, p==G[k+' output'], 'common:',common)

